import React, { useCallback } from "react";
import ConfirmationDialog from "components/ConfirmationDialog";
import { useDispatch, useSelector } from "react-redux";
import { Backdrop, CircularProgress } from "@mui/material";
import { deleteGuarantorByUuid } from "modules/credit-management/slices/guarantorSlice";
import { toast } from "react-toastify";
import { getGuarantors } from "modules/credit-management/slices/guarantorSlice";
import { deleteCollateral, getAllCollaterals } from "modules/loan-operation/slices/collateralSlice";

const ApplicationCollateralListDelete = ({
  open,
  onClose,
  selectedCollateral,
  applicationId
}) => {
  const dispatch = useDispatch();
  // const { isLoading } = useSelector(
  //   (state) => state.assessments.deleteAssessment
  // );
  const onOk = useCallback(async () => {
    try {
      await dispatch(
        deleteCollateral({ uuid: selectedCollateral?.uuid })
      ).unwrap();
      toast.success("Delete Success", {
        position: "top-right",
        autoClose: 3000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: undefined,
        theme: "light",
      });
      await dispatch(
        getAllCollaterals({
          params: {
            application_id:applicationId,
          },
        })
      );
    } catch (e) {}
  }, [dispatch, selectedCollateral?.id]);

  // if (isLoading) {
  //   return (
  //     <Backdrop
  //       sx={{ color: "#fff", zIndex: (theme) => theme.zIndex.drawer + 1 }}
  //       open={true}
  //     >
  //       <CircularProgress color="inherit" />
  //     </Backdrop>
  //   );
  // }

  return (
    <ConfirmationDialog
      open={open}
      onClose={onClose}
      onOk={onOk}
      title="Confirm Delete Collateral"
      content="Are you sure you want to delete this collateral?"
    />
  );
};

export default React.memo(ApplicationCollateralListDelete);
